return [
  {
    json: {
      nombre_cliente: 'Lucía Fernández Torres',
      email_cliente: 'lucia.fernandez@globaldev.io',
      plan_servicio: 'Suscripción Inmersiva Anual + Soporte 24/7',
      importe_total: '499.00'
    }
  }
];

// ==========================================================================
// Immersive Office - Inyección de Variables en Plantilla de Documento
// ==========================================================================
const inputItem = $input.first();
let rawHtml = "";

// Intentar leer binario del archivo HTML cargado
// n8n guarda binarios en modo filesystem: hay que pedir el buffer real,
// no leer binary.data.data (que solo contiene el marcador 'filesystem-v2').
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buf && buf.length) rawHtml = buf.toString('utf8');
} catch (e) {}
if (!rawHtml) {
  // Plantilla HTML corporativa de fallback para tests standalone
  rawHtml = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Contrato {{doc_id}}</title>
<style>body{font-family:sans-serif;padding:30px;line-height:1.6;color:#333;}.card{background:#f8f9fa;padding:20px;border-radius:8px;border:1px solid #e9ecef;}</style></head>
<body><h2>Acuerdo de Servicio Corporativo #{{doc_id}}</h2>
<div class="card"><p><strong>Cliente:</strong> {{nombre_cliente}}</p><p><strong>Email:</strong> {{email_cliente}}</p><p><strong>Plan Contratado:</strong> {{plan_servicio}}</p><p><strong>Importe Total:</strong> {{importe_total}} €</p><p><strong>Fecha de Emisión:</strong> {{fecha_emision}}</p></div></body></html>`;
}

// Obtener datos del cliente (desde webhook, mock data o fallback)
let customer = {};
try {
  customer = $('Datos de Prueba (Cliente Mock)').first()?.json || $('Webhook Trigger').first()?.json?.body || inputItem?.json?.body || inputItem?.json || {};
} catch (e) {
  customer = inputItem?.json?.body || inputItem?.json || {};
}

const nombre = customer.nombre_cliente || customer.nombre || customer.name || 'Cliente de Prueba';
const email = customer.email_cliente || customer.email || 'cliente@ejemplo.com';
const plan = customer.plan_servicio || customer.plan || 'Plan Profesional Inmersivo';
const importe = String(customer.importe_total || customer.importe || '499.00');
const docId = 'IO-' + Math.floor(100000 + Math.random() * 900000);
const fecha = new Date().toLocaleDateString('es-ES', { year: 'numeric', month: 'long', day: 'numeric' });

// Reemplazo de marcadores dinámicos
let renderedHtml = rawHtml
  .replace(/{{doc_id}}/g, docId)
  .replace(/{{nombre_cliente}}/g, nombre)
  .replace(/{{email_cliente}}/g, email)
  .replace(/{{plan_servicio}}/g, plan)
  .replace(/{{importe_total}}/g, importe)
  .replace(/{{fecha_emision}}/g, fecha);

const cleanName = nombre.toLowerCase().replace(/[^a-z0-9]/g, '_').replace(/_+/g, '_');
const filename = `contrato_${cleanName}_${docId}.html`;

return {
  json: {
    doc_id: docId,
    nombre_cliente: nombre,
    email_cliente: email,
    plan_servicio: plan,
    importe_total: importe,
    archivo_generado: filename,
    ruta_destino: `/data/output/${filename}`,
    fecha_emision: fecha,
    estado: "Documento Generado Exitosamente"
  },
  binary: {
    data: {
      data: Buffer.from(renderedHtml, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: filename
    }
  }
};
